const e={akai:[{counterId:"valir",reason:"Il knockback di Valir può spingerlo via anche durante la sua Ultimate."},{counterId:"diggie",reason:"La Ultimate di Diggie annulla completamente il blocco a muro di Akai per tutta la squadra."},{counterId:"claude",reason:"Estremamente mobile, può sfuggire facilmente alla sua Ultimate."}],aldous:[{counterId:"chou",reason:"Può schivare il pugno di Aldous con lo scatto e calciarlo sotto torre."},{counterId:"esmeralda",reason:"Ruba il massiccio scudo che Aldous genera coi pugni, diventando immortale."},{counterId:"twilight_armor",reason:"Menziona Oggetto: L'armatura Crepuscolare blocca il suo danno da oneshot."}],alice:[{counterId:"baxia",reason:"L'anti-cura passivo di Baxia annulla la sua immensa rigenerazione in Ultimate."},{counterId:"karrie",reason:"La scioglie con i danni puri ignorando gli HP extra."}],alpha:[{counterId:"valir",reason:"Lo tiene a distanza costante, impedendogli di curarsi con la passiva."},{counterId:"baxia",reason:"Riduce drasticamente il suo Spell Vamp (Ruba-vita abilità)."}],alucard:[{counterId:"khufra",reason:"Blocca il suo salto d'ingaggio impedendogli di avvicinarsi ai bersagli fragili."},{counterId:"baxia",reason:"Distrugge la sua immensa rigenerazione vitale da lifesteal."},{counterId:"chou",reason:"Lo isola dal teamfight annullando il suo potenziale AoE."}],angela:[{counterId:"carmilla",reason:"Quando Angela entra nel corpo di un alleato, Carmilla stordisce entrambi con la sua Ultimate."},{counterId:"baxia",reason:"Riduce drasticamente lo scudo e la cura che fornisce all'alleato."},{counterId:"esmeralda",reason:"Ruba il gigantesco scudo che Angela fornisce al suo compagno."}],argus:[{counterId:"valir",reason:"Lo tiene a distanza e lo stordisce mentre la sua Ultimate (immortalità) scade."},{counterId:"jawhead",reason:"Può lanciarlo via dal combattimento quando Argus attiva la Ultimate."},{counterId:"franco",reason:"La soppressione dura 1.8 secondi, facendogli sprecare tutta l'immortalità."}],atlas:[{counterId:"diggie",reason:"L'Ultimate di Diggie annulla completamente l'ingaggio AoE di Atlas per tutto il team."},{counterId:"valir",reason:"Lo respinge mentre cerca di avvicinarsi per usare la Ultimate."},{counterId:"chou",reason:"Può schivare la sua presa con facilità grazie all'immunità."}],aurora:[{counterId:"chou",reason:"Può schivare la sua mossa finale congelante ed eliminarla istantaneamente."},{counterId:"kagura",reason:"Il suo Purify integrato le permette di scappare dai blocchi di ghiaccio."}],badang:[{counterId:"chou",reason:"Può sfuggire al muro di Badang col suo scatto."},{counterId:"khufra",reason:"Evita che Badang scatti verso di lui per iniziare la combo."},{counterId:"esmeralda",reason:"Ruba il suo scudo vitale e ignora il suo muro balzando via."}],balmond:[{counterId:"valir",reason:"Lo spinge via e lo interrompe costantemente durante la sua rotazione."},{counterId:"dyrroth",reason:"Riduce la sua armatura a zero e lo shotta in scontro 1 contro 1."},{counterId:"karrie",reason:"Danni puri contro cui i massicci HP di Balmond sono inutili."}],bane:[{counterId:"chou",reason:"Alta mobilità per schivare la sua mossa finale a forma di squalo."},{counterId:"hayabusa",reason:"Lo assalta velocemente senza farsi colpire dalle aree d'effetto."}],barats:[{counterId:"karrie",reason:"I danni puri a percentuale ignorano del tutto le resistenze enormi di Barats."},{counterId:"valir",reason:"Lo brucia dalla distanza impedendogli di mantenere i suoi stack di grandezza."},{counterId:"xborg",reason:"Danni puri continui da lontano che sciolgono la sua armatura."}],baxia:[{counterId:"karrie",reason:"L'unico vero modo per sciogliere la sua drastica riduzione danni."},{counterId:"valir",reason:"Ferma il suo rotolamento istantaneamente col muro di fuoco."},{counterId:"lunox",reason:"Penetrazione magica pura che devasta la sua resistenza."}],belerick:[{counterId:"karrie",reason:"Danni puri. Evita i danni riflessi poiché Karrie non necessita di alta Attack Speed quanto Claude."},{counterId:"lunox",reason:"Danni percentuali pesanti che non innescano troppe volte la passiva di Belerick."},{counterId:"xborg",reason:"Lo scioglie lentamente con danni veri immuni al suo reflect ravvicinato."}],benedetta:[{counterId:"khufra",reason:"La sfera blocca tutti i suoi infiniti scatti, paralizzandola."},{counterId:"minsitthar",reason:"La sua Ultimate impedisce a Benedetta di usare qualsiasi abilità di scatto."},{counterId:"phoveus",reason:"Ogni volta che Benedetta scatta, Phoveus le salta addosso automaticamente."}],brody:[{counterId:"hayabusa",reason:"Può schivare il suo stun ed evadere l'Ultimate con la sua mossa finale."},{counterId:"chou",reason:"Può saltargli addosso immune ai suoi controlli e calciarlo."},{counterId:"ling",reason:"Troppo mobile per farsi colpire dai lenti attacchi base di Brody."}],bruno:[{counterId:"chou",reason:"Lo intercetta facilmente e lo elimina."},{counterId:"belerick",reason:"I danni critici continui di Bruno innescano pesantemente la passiva di riflesso danni."},{counterId:"natalia",reason:"Invisibilità e silenzio impediscono a Bruno di difendersi."}],carmilla:[{counterId:"diggie",reason:"Rimuove il link stordente della sua Ultimate dall'intero team alleato."},{counterId:"lunox",reason:"La penetrazione magica distrugge le resistenze che Carmilla ruba ai nemici."}],cecilion:[{counterId:"chou",reason:"Può infilarsi facilmente nella sua zona di sicurezza ravvicinata e ucciderlo."},{counterId:"ling",reason:"Arriva dai muri ignorando i danni ad area lontani di Cecilion."},{counterId:"hayabusa",reason:"Le sue ombre evitano le esplosioni e lo condannano a morte certa."}],change:[{counterId:"lolita",reason:"Lo scudo di Lolita blocca e assorbe l'INTERA Ultimate di Chang'e."},{counterId:"radiant_armor",reason:"Oggetto: Annulla letteralmente il DPS della sua pioggia di meteore."},{counterId:"chou",reason:"Può calciarla fuori posizione interrompendo l'angolo della sua Ultimate."}],chou:[{counterId:"khufra",reason:"Blocca lo scatto di Chou rendendo difficile ingaggiare."},{counterId:"barats",reason:"Se Chou lo calcia, Barats non si muove molto grazie alla passiva di tenacia, e poi lo mangia."},{counterId:"paquito",reason:"Può superarlo in danni e mobilità nei primissimi livelli."}],claude:[{counterId:"belerick",reason:"La Ultimate ad area di Claude attiva decine di volte la passiva di Belerick, suicidandosi."},{counterId:"blade_armor",reason:"Oggetto: Distrugge i suoi danni continui."},{counterId:"chou",reason:"Può stordirlo durante il teleport e calciarlo via interrompendo la Ultimate."}],clint:[{counterId:"brody",reason:"Lo batte in danni burst ravvicinati in corsia."},{counterId:"chou",reason:"Lo assalta facilmente schivando la rete (Skill 2) di Clint."},{counterId:"ling",reason:"Scende dall'alto evitandone il raggio di poke orizzontale."}],cyclops:[{counterId:"lancelot",reason:"L'immunità di Lancelot può schivare la Ultimate carceraria di Cyclops."},{counterId:"chou",reason:"Schiva il suo stun e lo uccide istantaneamente."},{counterId:"kagura",reason:"Usa il suo Purify integrato per liberarsi dalla Ultimate di Cyclops."}],diggie:[{counterId:"aldous",reason:"Diggie è fragilissimo e Aldous non si affida ai CC per shottarlo."},{counterId:"natalia",reason:"Lo elimina silenziandolo prima che possa usare l'Ultimate per salvare i compagni."}],dyrroth:[{counterId:"chou",reason:"Può schivare facilmente la sua letale ma lenta Ultimate."},{counterId:"paquito",reason:"Entra, fa danni e scappa prima che Dyrroth possa contrattaccare con l'armatura rotta."},{counterId:"thamuz",reason:"Riesce a reggere il suo scontro 1v1 prolungato grazie alla Ultimate."}],esmeralda:[{counterId:"baxia",reason:"La sua passiva annulla le cure e la rigenerazione degli scudi di Esmeralda."},{counterId:"karrie",reason:"I danni puri ignorano del tutto gli scudi massicci che accumula."},{counterId:"lunox",reason:"Burst magico devastante contro cui gli scudi reggono poco."}],estes:[{counterId:"baxia",reason:"Taglia drasticamente tutte le cure AoE per l'intero team."},{counterId:"luo_yi",reason:"Quando Estes cura, il team nemico si raggruppa: Luo Yi li fa esplodere tutti insieme con la reazione Yin-Yang."},{counterId:"atlas",reason:"Prende tutto il team raggruppato da Estes e li sbatte in aria."}],eudora:[{counterId:"lancelot",reason:"Può schivare il suo stun mortale con la Skill 2 e poi ucciderla."},{counterId:"chou",reason:"Può usare l'immunità al momento giusto per evitare il suo intero burst."},{counterId:"athenas_shield",reason:"Oggetto: L'unico modo certo per sopravvivere al suo oneshot."}],fanny:[{counterId:"khufra",reason:"La sua forma a palla blocca fisicamente le corde di Fanny, fermandola a mezz'aria."},{counterId:"chou",reason:"Richiede tempismo, ma il suo calcio finale la blocca senza possibilità di scampo."},{counterId:"moskov",reason:"Il suo attacco repulsivo può inchiodare Fanny a un muro mentre vola, condannandola."},{counterId:"ruby",reason:"Le sue abilità attirano costantemente Fanny a terra, rovinando le traiettorie dei cavi."}],faramis:[{counterId:"valentina",reason:"Copia la Ultimate di Faramis, garantendo immortalità anche al suo team."},{counterId:"yin",reason:"Rapisce Faramis nella sua arena isolandolo dal team, impedendogli di salvare i compagni."},{counterId:"akay",reason:"Spinge via i nemici dal raggio della Ultimate di Faramis prima che resuscitino."}],floryn:[{counterId:"baxia",reason:"L'unico vero e affidabile anti-cura in grado di competere con le cure globali di Floryn."},{counterId:"natalia",reason:"Essendo fragile, Natalia può silenziarla e farla sparire istantaneamente."}],franco:[{counterId:"diggie",reason:"Anche se Franco sopprime qualcuno, Diggie dona scudi per farlo sopravvivere o purifica il resto del team."},{counterId:"johnson",reason:"Se Franco prova ad agganciarlo, tira a sé un tank corazzatissimo a suo svantaggio."}],fredrinn:[{counterId:"karrie",reason:"L'unico modo per abbatterlo prima che accumuli la sua letale Ultimate a danno puro."},{counterId:"baxia",reason:"Riduce il suo sustain e la sua efficacia negli scontri prolungati."},{counterId:"valir",reason:"Lo respinge costantemente impedendogli di accumulare cristalli colpendo da vicino."}],freya:[{counterId:"esmeralda",reason:"Ruba l'enorme scudo che Freya genera in Ultimate, surclassandola in corpo a corpo."},{counterId:"minsitthar",reason:"La sua Ultimate impedisce a Freya di usare i suoi salti offensivi."},{counterId:"valir",reason:"Non la lascia avvicinare."}],gatotkaca:[{counterId:"karrie",reason:"Ignora completamente le tonnellate di armatura fisica che accumula la sua passiva."},{counterId:"lunox",reason:"La penetrazione magica dissolve le sue difese spesse."},{counterId:"diggie",reason:"Annulla il CC del suo atterraggio esplosivo per tutta la squadra."}],gloo:[{counterId:"farams",reason:"Il rimbalzo magico di Faramis sui cloni piccoli di Gloo infligge danni devastanti al bersaglio originale e a chiunque sia vicino."},{counterId:"vexana",reason:"La passiva di esplosione si innesca su tutti i micro-gloo creando una reazione a catena letale."},{counterId:"claude",reason:"Sfrutta i cloni di Gloo per curarsi istantaneamente con l'attack speed."}],gord:[{counterId:"chou",reason:"Entra nel suo fianco cieco ed elude il laser facilmente."},{counterId:"fanny",reason:"Gord non ha modo di fuggire dai suoi cavi fulminei."},{counterId:"ling",reason:"Può atterrare esattamente dietro di lui mentre incanala il raggio."}],granger:[{counterId:"chou",reason:"Alta mobilità per schivare le sue raffiche di proiettili."},{counterId:"khufra",reason:"Blocca il suo prezioso scatto (Skill 2) disarmandolo posizionalmente."}],grock:[{counterId:"karrie",reason:"Scioglie la sua colossale armatura vicina ai muri."},{counterId:"x_borg",reason:"I danni puri lo annientano ignorando l'armatura fisica."},{counterId:"valir",reason:"Impedisce le sue cariche distruttive col muro di fiamme."}],guinevere:[{counterId:"chou",reason:"Può schivare il suo salto prevedibile e punirla."},{counterId:"khufra",reason:"Blocca il salto di Guinevere facendola cadere rovinosamente prima del knockup."},{counterId:"diggie",reason:"Annulla l'immobilizzazione del suo salto salvando chiunque venga colpito."}],gusion:[{counterId:"khufra",reason:"Se Gusion prova a balzare sui pugnali, la sfera lo sbalza via."},{counterId:"chou",reason:"Può schivare la mossa letale a bruciapelo e stordirlo durante l'avanzata."},{counterId:"ruby",reason:"Lo interrompe più volte durante le sue veloci concatenazioni."}],hanabi:[{counterId:"chou",reason:"Anche se Hanabi ha lo scudo immunità, il calcio di Chou distrugge lo scudo e la uccide se buildato danni."},{counterId:"hayabusa",reason:"Troppo mobile, il rimbalzo di Hanabi non lo colpisce, e lui la shotta."},{counterId:"blade_armor",reason:"Oggetto: Punisce severamente la sua natura statica e il rimbalzo automatico."}],harith:[{counterId:"esmeralda",reason:"Il peggior incubo di Harith: ruba ogni singolo scudo che lui genera scattando."},{counterId:"khufra",reason:"Mentre Harith scatta avanti e indietro, la sfera di Khufra lo stordisce ripetutamente."},{counterId:"minsitthar",reason:"La sua Ultimate vieta letteralmente ad Harith di scattare."}],harley:[{counterId:"chou",reason:"Può schivare le sue carte e il cappello usando l'immunità al momento giusto."},{counterId:"radiant_armor",reason:"Oggetto: L'armatura riduce enormemente il danno accumulato dai colpi multipli di Harley."},{counterId:"lolita",reason:"Lo scudo blocca tutta la sventagliata di carte, azzerando l'esplosione dell'Ultimate."}],hayabusa:[{counterId:"chou",reason:"Riesce a prenderlo e tenerlo bloccato ignorando la sua mobilità."},{counterId:"khufra",reason:"Gli impedisce di usare le ombre per teletrasportarsi comodamente."},{counterId:"ruby",reason:"Lo blocca e lo attira a terra costantemente durante i suoi movimenti furtivi."}],helcurt:[{counterId:"chou",reason:"Sopravvive al suo silenzio iniziale e poi contrattacca con forza letale."},{counterId:"hylos",reason:"Troppi HP e un veleno costante che impedisce a Helcurt di muoversi velocemente e assassinarlo."},{counterId:"natalia",reason:"La vera regina del silenzio, colpisce prima che Helcurt se ne accorga."}],hilda:[{counterId:"valir",reason:"Impedisce la sua carica feroce dai cespugli spingendola via."},{counterId:"karrie",reason:"Distrugge i suoi ampi scudi e PV massicci con danni veri in pochi secondi."}],hylos:[{counterId:"karrie",reason:"Hylos ha gli HP più alti del gioco; Karrie infligge danni percentuali basati sui massimi HP."},{counterId:"claude",reason:"La DHS (Demon Hunter Sword) lo rende formaggio fuso."},{counterId:"valir",reason:"Rallenta e brucia Hylos che cerca di correre lungo la sua Ultimate, bloccandolo."}],irithel:[{counterId:"chou",reason:"Colma rapidamente la distanza e la blocca impedendole di fuggire sparando."},{counterId:"hayabusa",reason:"Assassino puro che la disintegra prima che la sua armatura scenda a livelli critici."}],ixia:[{counterId:"lolita",reason:"Il suo scudo frontale BLOCCA TUTTA l'immensa Ultimate di Ixia, rendendola inutile."},{counterId:"kadita",reason:"Si infiltra facilmente sotto terra per oneshottare Ixia mentre è immobile nell'Ultimate."},{counterId:"chou",reason:"Entra nella sua zona e la calcia fuori dalla propria Ultimate interrompendola."}],jawhead:[{counterId:"valir",reason:"Se Jawhead corre per lanciare qualcuno, Valir lo spinge via ripetutamente."},{counterId:"khufra",reason:"Gli impedisce di balzare addosso a compagni deboli."},{counterId:"chou",reason:"Immune al suo lancio se usa bene la seconda abilità."}],johnson:[{counterId:"grock",reason:"Usa il suo muro per bloccare letteralmente la strada alla macchina di Johnson, schiantandolo prima del tempo."},{counterId:"diggie",reason:"Al momento dell'impatto, attiva la Ultimate e rimuove lo stun per tutti."},{counterId:"akai",reason:"La sua mossa finale fa rimbalzare via Johnson prima che causi danni critici."}],joy:[{counterId:"minsitthar",reason:"L'arena vieta tassativamente i Dash di Joy, rendendola del tutto inerte."},{counterId:"phoveus",reason:"Dato che Joy fa 4 scatti di fila, Phoveus può balzarle in testa per 4 volte causando devastazione."},{counterId:"franco",reason:"L'unico che può sopprimerla bloccando il suo ritmo e cancellando l'immunità."}],julian:[{counterId:"chou",reason:"Evasivo, schiva le sue skill potenziate che richiedono mira e cast-time alto."},{counterId:"valir",reason:"Spinge via Julian prima che possa concludere le sue combo in corpo a corpo."},{counterId:"phoveus",reason:"Julian usa degli scatti vitali per la mobilità; Phoveus lo punisce pesantemente."}],kadita:[{counterId:"lancelot",reason:"Usa l'immunità per schivare l'ondata annegante letale di Kadita."},{counterId:"chou",reason:"Può saltarle via mentre si emerge dal terreno."},{counterId:"athenas_shield",reason:"Oggetto: Vitale per sopravvivere alla sua esplosione improvvisa."}],kagura:[{counterId:"gusion",reason:"Può infilarsi nel suo raggio di sicurezza ed eliminarla prima che scappi."},{counterId:"chou",reason:"Anche se Kagura si purifica, Chou può rincorrerla col suo doppio scatto."}],kaja:[{counterId:"valir",reason:"Non permette a Kaja di avvicinarsi per usare la sua letale soppressione (Ultimate)."},{counterId:"diggie",reason:"Può purificare i compagni dalle catene base (non l'Ultimate, ma aiuta)."}],karina:[{counterId:"chou",reason:"L'immunità agli attacchi base di Karina è inutile contro i danni da abilità pura di Chou."},{counterId:"khufra",reason:"Rovinerà i suoi reset di scatti impedendole di uccidere a catena."}],karrie:[{counterId:"chou",reason:"Un assassino / fighter letale è l'unica via; i Tank con Karrie sciolgono come neve al sole."},{counterId:"natalia",reason:"La silenzia, e il fumo le impedisce di usare gli attacchi base penetranti."},{counterId:"lolita",reason:"Riflette tutte le frecce veloci di Karrie, azzerando i suoi danni per 3 preziosi secondi."}],khaleed:[{counterId:"chou",reason:"Il suo stun interrompe brutalmente la guarigione di Khaleed (Skill 2) e schiva la mossa finale."},{counterId:"valir",reason:"Respinge l'area della sua Ultimate tenendolo perennemente sotto scacco."}],khufra:[{counterId:"valir",reason:"Il nemico naturale dei tank da ingaggio. Lo spinge via mentre prova a balzare."},{counterId:"diggie",reason:"Purifica tutto il team dopo il grande salto di Khufra, annullando il suo ruolo."},{counterId:"karrie",reason:"La sua penetrazione pura scinde le difese extra che Khufra guadagna in modalità palla."}],kimmy:[{counterId:"lolita",reason:"L'intero kit di Kimmy è a proiettili base, che Lolita blocca interamente."},{counterId:"chou",reason:"Schiva i suoi colpi direzionali muovendosi lateralmente per finirla."},{counterId:"radiant_armor",reason:"Oggetto: Riduce clamorosamente il danno rapido e prolungato di Kimmy."}],lancelot:[{counterId:"khufra",reason:"Fermo, a terra! Khufra impedisce le triangolazioni perfette di Lancelot."},{counterId:"chou",reason:"Aspetta che Lancelot esaurisca gli scatti e lo isola con un calcio letale."},{counterId:"phoveus",reason:"Phoveus si esalta. Più Lancelot scatta (e ne ha tantissimi), più Phoveus spacca teste."}],lapulapu:[{counterId:"chou",reason:"Può calciare via Lapu-Lapu proprio mentre atterra per fare i grossi danni AoE."},{counterId:"valir",reason:"Spinge via Lapu-Lapu mentre brandisce gli spadoni in modalità pesante."},{counterId:"esmeralda",reason:"Ruba il grosso scudo che Lapu guadagna nella Ultimate."}],layla:[{counterId:"natalia",reason:"Appare da dietro, silenzia, shotta. Layla non ha via di scampo (zero mobilità)."},{counterId:"chou",reason:"Vola attraverso la mappa ignorando i danni di Layla e la elimina."},{counterId:"ling",reason:"Piomba da un muro inarrivabile per i compagni di Layla e la rimuove in 1 secondo."}],leomord:[{counterId:"valir",reason:"Spinge via il cavallo e rallenta pesantemente i suoi danni corpo a corpo."},{counterId:"chou",reason:"Può schivare le sue stoccate critiche."}],lesley:[{counterId:"aldous",reason:"L'Ultimate di Aldous la vede in mappa anche se invisibile, rendendole impossibile nascondersi."},{counterId:"chou",reason:"Arriva in mischia velocemente e la uccide."},{counterId:"twilight_armor",reason:"Oggetto: Vitale contro i suoi colpi critici a Danno Puro enormi."}],ling:[{counterId:"khufra",reason:"Mentre Ling viaggia a terra o scende dai muri, la sfera lo sbalza via pesantemente."},{counterId:"minsitthar",reason:"Se usa la Ultimate sotto Ling, lui non può usare il salto verso le spade (Skill 2)."},{counterId:"ruby",reason:"I suoi agganci aerei rovinano completamente la fuga e l'Ultimate di Ling."}],lolita:[{counterId:"esmeralda",reason:"Lo scudo gigante che Lolita garantisce è un buffet gratis per Esmeralda."},{counterId:"chou",reason:"In grado di interrompere il caricamento lento della sua Ultimate."},{counterId:"valir",reason:"Dato che Valir colpisce parzialmente col fuoco a terra, aggira i limiti dello scudo frontale di Lolita."}],lunox:[{counterId:"chou",reason:"Se presa nel momento scuro, è un bersaglio facile prima che voli via."},{counterId:"lolita",reason:"Lo scudo frontale assorbe TUTTA la raffica violenta della Ultimate Oscura di Lunox."}],luo_yi:[{counterId:"chou",reason:"Alta mobilità per evitare le zone Yin-Yang di scontro magico."},{counterId:"lancelot",reason:"Può usare l'invulnerabilità per evitare i danni reattivi di massa."}],lylia:[{counterId:"chou",reason:"Forza la sua Ultimate e la riagguanta grazie al doppio scatto e al calcio."},{counterId:"gusion",reason:"I pugnali possono inseguirla rapidamente prima che lei capisca di dover tornare indietro nel tempo."}],martis:[{counterId:"chou",reason:"Può schivare i suoi fendenti lenti e la mossa finale."},{counterId:"valir",reason:"Lo rallenta all'inverosimile, rendendo inefficace la rincorsa selvaggia di Martis (anche se ha l'immunità, perde raggio d'azione)."},{counterId:"phoveus",reason:"Punisce gli scatti continui di Martis (Skill 2) spaccandogli il martello in testa."}],masha:[{counterId:"chou",reason:"La fa rimbalzare a terra azzerando la sua spaventosa aggressione auto-attaccante."},{counterId:"baxia",reason:"La passiva anti-cura riduce il suo recupero estremo tra una barra HP e l'altra."},{counterId:"dominance_ice",reason:"Oggetto: Assolutamente fondamentale contro i suoi letali colpi base velocissimi."}],mathilda:[{counterId:"khufra",reason:"Ferma i salti dei compagni di squadra portati da Mathilda, paralizzandoli a mezz'aria."},{counterId:"chou",reason:"Interrompe il suo circolare incantesimo di sfere colpendola col calcio."}],melissa:[{counterId:"franco",reason:"La soppressione ignora del tutto la bolla repulsiva della sua Ultimate, intrappolandola."},{counterId:"pharsa",reason:"Danni enormi dall'alto (Ultimate) che ignorano del tutto la bolla protettiva a terra."},{counterId:"yve",reason:"La rallenta e la brucia stando ampiamente fuori dalla portata della sua barriera anti-corpo a corpo."}],minotaur:[{counterId:"diggie",reason:"Il counter perfetto per qualsiasi Tank pesante: l'Ultimate purifica l'intera serie di terremoti sollevanti."},{counterId:"valir",reason:"Lo blocca prima che salti al centro della squadra arrabbiato."}],miya:[{counterId:"chou",reason:"Si fionda nella backline ignorando il resto del team, sottomettendo Miya."},{counterId:"natalia",reason:"Assassina per eccellenza contro eroi statici senza escape passivi."},{counterId:"saber",reason:"Un pulsante = Una kill su Miya (se buildato full penetrazione)."}],nana:[{counterId:"lancelot",reason:"L'immunità della Skill 2 permette di distruggere il fastidiosissimo orsacchiotto Molina senza trasformarsi."},{counterId:"chou",reason:"Rapido e capace di inseguirla anche dopo che ha usato la sua passiva di immortalità trasformista."}],natalia:[{counterId:"hylos",reason:"Il cerchio magico di Hylos annulla istantaneamente l'invisibilità di Natalia quando prova ad avvicinarsi (il danno svela l'ombra)."},{counterId:"rafaela",reason:"La sua Skill 1 la rivela nel cespuglio, counter naturale assoluto."},{counterId:"aldous",reason:"L'Ultimate svela tutti, annullando totalmente la sua peculiarità furtiva su mappa globale."}],natan:[{counterId:"chou",reason:"Stordimento brutale che impedisce a Natan di accumulare gli strati mortali di Attack Speed."},{counterId:"lolita",reason:"Scudo impenetrabile contro i suoi proiettili a boomerang."}],nolan:[{counterId:"khufra",reason:"L'arma migliore contro le sue scivolate multidirezionali letali."},{counterId:"minsitthar",reason:"Vieta del tutto gli scatti di Nolan, trasformandolo in un bersaglio statico."},{counterId:"phoveus",reason:"Godrà di Ultimate infinite viste le costanti fenditure e salti di Nolan."}],novaria:[{counterId:"ling",reason:"Si sposta sui muri arrivando direttamente in fondo alla mappa, raggiungendo l'estrema gittata di Novaria."},{counterId:"fanny",reason:"La insegue e l'abbatte ignorando i laser e attraversando i muri in un battito di ciglia."}],odette:[{counterId:"chou",reason:"Un calcio rapido e addio Ultimate ad area letale."},{counterId:"valir",reason:"Il knockback (Skill 2) interrompe all'istante l'Ultimate cantata da Odette."},{counterId:"franco",reason:"Il suo amo tira Odette fuori posizione o la morde sopprimendola."}],paquito:[{counterId:"khufra",reason:"I molteplici scatti pugilistici di Paquito si schiantano contro la palla di Khufra."},{counterId:"phoveus",reason:"Paquito usa troppi scatti per le sue combo, innescando a raffica la mossa letale di Phoveus."},{counterId:"valir",reason:"Rallentamento e repulsione costanti, Paquito non lo toccherà mai."}],pharsa:[{counterId:"chou",reason:"Può schivare facilmente i cerchi esplosivi e sbalzarla dal suo incantesimo volatile."},{counterId:"ling",reason:"Un Assassino che raggiunge le retrovie scende dalle pareti dritto su Pharsa."},{counterId:"franco",reason:"L'amo trascina Pharsa fuori dal cerchio letale (la skill s'interrompe all'istante)."}],phoveus:[{counterId:"esmeralda",reason:"Il peggior counter: Phoveus genera enormi scudi saltando, Esmeralda glieli ruba tutti annientandolo."},{counterId:"lunox",reason:"Scioglie i suoi scudi massicci con Danno Percentuale puro e penetrante."}],popol:[{counterId:"claude",reason:"Usa il lupo (Kupa) per teletrasportarsi e come rimbalzo per l'Ultimate."},{counterId:"chou",reason:"Vola letteralmente sopra Kupa e shotta Popol ignorando il lupo protettore."}],rafaela:[{counterId:"chou",reason:"Assassina istantaneamente il supporto evitando le cure ad area."},{counterId:"natalia",reason:"Se presa di sorpresa prima di poter usare la Skill 1, viene silenziata a morte."}],roger:[{counterId:"khufra",reason:"Blocca l'importante balzo del lupo, rovinando il burst e la via di fuga."},{counterId:"baxia",reason:"Anti-cura naturale che riduce enormemente il sustain vitale in mischia di Roger."},{counterId:"valir",reason:"Respinge e brucia il lupo mentre tenta gli sbranamenti frenetici."}],ruby:[{counterId:"baxia",reason:"Il Re dell'Anti-cura. Senza la sua mostruosa rigenerazione di Spell Vamp, Ruby è morta."},{counterId:"valir",reason:"La brucia e la respinge mantenendosi fuori dalla portata mortale della sua falce."},{counterId:"karrie",reason:"La fa a pezzi in pochi colpi veri."}],saber:[{counterId:"argus",reason:"L'immortalità impedisce a Saber di uccidere, costringendolo a sprecare l'esecutrice."},{counterId:"chou",reason:"Difficile da colpire con l'Ultimate, può annullarla se gioca di tempismo."},{counterId:"wind_of_nature",reason:"Oggetto: Tiratori che lo attivano nel momento esatto assorbono l'Ultimate a zero danni."}],selena:[{counterId:"chou",reason:"Sfugge agilmente alla lenta (ma mortale) freccia abissale e la sanziona severamente."},{counterId:"diggie",reason:"Annulla le storditure lunghe 3 secondi e rivela le trappole (mine) nascoste nei cespugli."}],sun:[{counterId:"ruby",reason:"Usa le centinaia di cloni di Sun come fonte di vita gratuita per rubare HP a profusione (Spell Vamp)."},{counterId:"esmeralda",reason:"Stessa logica, colpire più cloni raddoppia l'efficacia del suo sustain."},{counterId:"odette",reason:"La Ultimate di Odette rimbalza e distrugge istantaneamente il vero e i finti cloni per via dell'AoE massivo."}],terizla:[{counterId:"valir",reason:"La sua più grande debolezza è la lentezza e la goffaggine. Valir lo trasforma in un pupazzo ardente."},{counterId:"karrie",reason:"I danni puri a scatti rapidi penetrano l'impenetrabile riduzione del danno innata di Terizla."},{counterId:"chou",reason:"Entra e fa danni uscendo prima del tonfo letale del martello, giocando sui tempi."}],thamuz:[{counterId:"baxia",reason:"La fornace curativa di Thamuz è potentissima. Baxia la spegne col 50% di anti-cura."},{counterId:"karrie",reason:"Ignora completamente il sustain di base infliggendo danni veri percentuali massicci."},{counterId:"valir",reason:"Lo spinge via e lo stordisce bloccando i suoi DPS frenetici ravvicinati."}],tigreal:[{counterId:"diggie",reason:"Il salvavita supremo. Tigreal Ultimate > Diggie Ultimate > Tutti salvi e Tigreal inutile."},{counterId:"valir",reason:"Lo sbalza via ogni volta che prova ad avvicinarsi."},{counterId:"akai",reason:"Gira interrompendo immediatamente e goffamente la mossa finale del paladino."}],vale:[{counterId:"chou",reason:"L'immunità allo stun del tornado e il calcio sono troppo veloci per il fragile mago dell'aria."},{counterId:"lancelot",reason:"Attraversa il suo mortale ciclone con perfetta invulnerabilità eliminandolo."},{counterId:"ling",reason:"Irrompe lateralmente sui muri impossibile da mirare col tornado base."}],valentina:[{counterId:"chou",reason:"Può schivarla facilmente ed eseguire un lockdown. E rubare l'Ultimate di Chou non le dà i veri danni letali."},{counterId:"hayabusa",reason:"L'Ultimate di Hayabusa su di lei la uccide, mentre lei rubandola non saprà come accumulare i marchi base."}],valir:[{counterId:"chou",reason:"Lo scatto e il tempismo gli permettono di non farsi colpire dalle palle di fuoco."},{counterId:"ling",reason:"Molto ostico per Valir colpirlo mentre salta tra le pareti."},{counterId:"hayabusa",reason:"Il teletrasporto ombra aggira il knockback e l'Ultimate di Hayabusa lo condanna."}],vexana:[{counterId:"chou",reason:"Evita la terrificante prigione spettrale per piombare sul debole scheletro della maga."},{counterId:"lancelot",reason:"L'immunità rende inutile il massiccio signore della morte (Cavaliere)."},{counterId:"athenas_shield",reason:"Oggetto: Fondamentale per arginare il terrificante burst ad area del Cavaliere."}],xborg:[{counterId:"chou",reason:"Se riesce a rompergli l'armatura e calciare, X.Borg è disarmato ed estremamente vulnerabile."},{counterId:"karrie",reason:"Danni veri per un eroe che si basa solo sul sustain HP, Karrie lo distrugge."},{counterId:"esmeralda",reason:"I danni ravvicinati di Esmeralda infrangono la sua armatura ignorando il fuoco leggero iniziale."}],xavier:[{counterId:"ling",reason:"La distanza per Xavier è sicurezza. Ling scavalca le enormi distanze e l'immobilizzazione a terra non lo tange se atterra bene."},{counterId:"fanny",reason:"Cavi veloci in volto, Xavier non ha escape ed evapora."}],yisunshin:[{counterId:"chou",reason:"Alta mobilità per schivare il suo fendente in avanti e colpirlo duro."},{counterId:"khufra",reason:"Lo blocca se YSS prova a scivolare per resettare la sua passiva o evitare minacce."}],yin:[{counterId:"valir",reason:"All'interno dell'Arena di Yin, Valir lo spinge via e lo immobilizza col fuoco, rovinando del tutto la sua combo esplosiva per tutti i 5 secondi."},{counterId:"wanwan",reason:"Nell'arena, Yin fornirà facilmente l'attivazione della Ultimate a Wanwan, decretando la sua morte."},{counterId:"argus",reason:"Se Yin rapisce Argus, Argus attiva l'Immortalità e Yin finisce brutalmente massacrato nella sua stessa trappola."}],yuzhong:[{counterId:"baxia",reason:"Yu Zhong vive del rubavita mostruoso dell'essenza nera (Sha). Baxia taglia quella cura rendendolo mortale."},{counterId:"karrie",reason:"Il suo enorme corpo draconico è il bersaglio perfetto per i danni percentuali inarrestabili."},{counterId:"sea_halberd",reason:"Oggetto: Ogni attaccante fisico deve comprarlo o Yu Zhong risucchierà tutto il team."}],yve:[{counterId:"franco",reason:"Durante la colossale scacchiera immuni ai CC, Franco la sopprime spegnendo letteralmente il tabellone."},{counterId:"kaja",reason:"Anche lui usa la Soppressione, disarmandola dal cast."},{counterId:"chou",reason:"Entra nella board se vicino ai bordi e usa il calcio (che è un Knockback forte e la disattiva)."}],zhask:[{counterId:"claude",reason:"Può svanire col teletrasporto ed eludere completamente il laser del mostro gigante (Spawn)."},{counterId:"radiant_armor",reason:"Oggetto: Obbligatorio. Zhask infligge migliaia di colpi magici leggeri in sequenza. La Radiant lo annulla."},{counterId:"chou",reason:"Se intercettato senza il suo mostro-torretta al fianco, Zhask è inerme."}],zhuxin:[{counterId:"khufra",reason:"Le impedisce scatti mentre cerca di riposizionarsi col suo campo lanterna."},{counterId:"ling",reason:"Piomba rapido per evadere il CC prolungato (Airborne accumulato)."}],zilong:[{counterId:"chou",reason:"Se Zilong cerca di ribaltarlo, Chou lo anticipa col calcio inarrestabile."},{counterId:"khufra",reason:"Zilong corre verso di te a folle velocità e si schianta contro la sfera dura di Khufra."},{counterId:"ruby",reason:"Lifesteal incredibile che surclassa i colpi singoli di Zilong."}],aamon:[{counterId:"radiant_armor",reason:"I cocci di vetro magici (shards) di Aamon colpiscono in rapida serie, questo item dimezza tutti i danni."},{counterId:"chou",reason:"Riesce a prevedere o intercettare la sua comparsa mimetica per sbalzarlo prima della Ultimate."},{counterId:"ruby",reason:"Attrae Aamon al centro bloccandone l'escape invisibile in mischia."}],aulus:[{counterId:"valir",reason:"Lo spinge via e lo ustiona ripetutamente impedendo ad Aulus (lento in early game) di attaccare pesantemente."},{counterId:"chou",reason:"Può isolare il guerriero da mischia dal suo team eludendo il grosso impatto ad area della Ultimate."},{counterId:"khufra",reason:"Rimbalzando neutralizza i potenziamenti del suo movimento rapido (Skill 1)."}],arlott:[{counterId:"khufra",reason:"Il peggior incubo di Arlott. Senza i suoi scatti multipli sul Marchio, Arlott diventa un pupazzo."},{counterId:"minsitthar",reason:"L'arena disabilita totalmente gli scatti mortali concatenati che caratterizzano il campione."},{counterId:"phoveus",reason:"Gioia per Phoveus: Arlott fa decine di scatti, garantendo al distruttore magico salti infiniti."}],beatrix:[{counterId:"chou",reason:"Ignora i lunghi fucili da cecchino o i colpi rapidi e le salta addosso senza darle modo di mirare."},{counterId:"natalia",reason:"Se presa fuori guardia e silenziata prima del fucile a pompa, evapora."},{counterId:"blade_armor",reason:"Oggetto: Essenziale per bloccare i suoi folli colpi penetranti del Nibiru (mitragliatrice)."}],cici:[{counterId:"khufra",reason:"Cici fa costantemente saltelli continui che Khufra blocca impetuosamente con la palla."},{counterId:"valir",reason:"I danni costanti a raggio maggiore fermano lo yoyo e rallentano gravemente il suo stile basato sulla Movement Speed."},{counterId:"phoveus",reason:"Punisce gli scatti integrati dello yoyo distruggendole letteralmente la testa (in game)."}],chip:[{counterId:"valir",reason:"Sbalza Chip via ogni volta che entra per immobilizzare il gruppo."},{counterId:"diggie",reason:"Rimuove il massiccio Stun e disorientamento provocati dai portali globali e teletrasporti di squadra."}],edith:[{counterId:"karrie",reason:"Quando Edith non è nel robot (Ultimate) perde difese e guadagna rubavita magico; i danni percentuali la annientano in entrambe le forme."},{counterId:"valir",reason:"Respinta quando usa il colpo sollevante, impedendole di fare le sue pesanti combo da Tank."},{counterId:"baxia",reason:"Distrugge le massicce cure magiche a lungo termine di Edith in forma finale."}],hanzo:[{counterId:"natalia",reason:"Il vero counter puro. Quando Hanzo usa lo spirito fantasma, il suo vero corpo resta immobile nei cespugli. Natalia lo cerca colla sua immunità e lo shotta."},{counterId:"ling",reason:"Può volare oltre le torri per trovare il corpo dormiente e sopprimerlo in due secondi."},{counterId:"aldous",reason:"Svela l'intera mappa. Vede l'esatta posizione del vero corpo vulnerabile di Hanzo per schiantarsi contro di lui."}],minsitthar:[{counterId:"chou",reason:"Anche con il muro disabilita-scatti, Chou ha la tenacia di resistere o uscire fuori a piedi prima che la palla di guardie lo finisca."},{counterId:"valir",reason:"Evita che si avvicini per lanciare la lancia-scudo o lo allontana se prova a ingaggiare col salto."}],silvanna:[{counterId:"diggie",reason:"Anche se salta imprigionando un bersaglio, Diggie può usare Ultimate e liberarlo, rendendola quasi inutile nel teamfight."},{counterId:"chou",reason:"Evasione suprema per sfuggire all'Area di Salto (Ultimate) e interrompere il suo trapanamento abilità."},{counterId:"kadita",reason:"Si rituffa nei fondali ignorando la gabbia ed esplodendola dall'interno."}],suyou:[{counterId:"chou",reason:"Gli scatti o le forme trasformate di Suyou possono essere bloccate dal calcio prepotente di un provetto Chou."},{counterId:"khufra",reason:"Bouncer perfetto che stordisce in volo l'Assassino evitando che uccida i maghi amici."}],wanwan:[{counterId:"khufra",reason:"I saltelli (dash) continui di Wanwan (ogni singolo attacco) vengono bloccati a ripetizione, annientandola fisicamente."},{counterId:"phoveus",reason:"Essendo letteralmente composta da Dash (Scatti) ad ogni salto, dona Ultimate libere a Phoveus che la pialla saltandole addosso senza sosta."},{counterId:"franco",reason:"Soppressione brutale che neutralizza la sua alta mobilità."}],lukas:[{counterId:"khufra",reason:"Interrompe i tentativi d'ingaggio dell'eroe annullandone le mobilità di base."},{counterId:"chou",reason:"Evade le sue combo pesanti sbalzandolo fuori portata o sotto torre alleata."}],moskov:[{counterId:"belerick",reason:"Uno scontro fatale: la massiccia Attack Speed di Moskov contro Belerick innescherà spine (riflesso danni) e Vengeance, suicidando il tiratore in 2 secondi."},{counterId:"blade_armor",reason:"Oggetto: Rimanda le lance velenose indietro (20% del danno)."},{counterId:"chou",reason:"Schiva il suo stun (lancia al muro) per atterrarlo senza preavviso."}],uranus:[{counterId:"baxia",reason:"Uranus guarisce se stesso enormemente. Baxia rende questo eroe un sasso senza cura, distruggendo il 50% di regen."},{counterId:"esmeralda",reason:"Ruba il suo piccolo scudo accumulato trasformando l'incontro nella corsia superiore in una vittoria totale."},{counterId:"karrie",reason:"L'esecutore vero e proprio per eccellenza. Distrugge PV puri veloci che Uranus non può bilanciare."}],kalea:[{counterId:"baxia",reason:"L'anti-cura blocca le meccaniche di guarigione o l'utilità del kit orientato al supporto magico."},{counterId:"chou",reason:"Può cacciare un eroe leggero/Supporto e toglierlo dall'ingaggio rapido."}],zetian:[{counterId:"chou",reason:"Puo sfuggire alla maggior parte delle abilità AoE di Zetian scattando e punendola nel corpo a corpo."},{counterId:"lancelot",reason:"Non essendoci protezioni ravvicinate vere, i suoi scatti immuni trafiggeranno la linea della maga."}],obsidia:[{counterId:"natalia",reason:"Tiratore statico pesante, se non ha visione viene silenziato e disintegrato dal fumo mortale."},{counterId:"belerick",reason:"Riflette l'elevato danno da auto-attack distruggendolo con la sua stessa potenza."}],sora:[{counterId:"khufra",reason:"La sfera disarma la mobilità esplosiva di questo assassino prima che possa ingaggiare pesantemente."},{counterId:"chou",reason:"Blocca l'offensiva colpendolo o schivando l'apertura principale del suo attacco letale."}],marcel:[{counterId:"baxia",reason:"Distrugge completamente la cura e il ruolo logistico primario di questo Support."},{counterId:"natalia",reason:"Senza difese forti corporee, Natalia esplode Marcel nel cespuglio silenziando ogni speranza di cura o reazione."}]},o=a=>e[a.toLowerCase()]||[{counterId:"chou",reason:"Generic Counter: Grazie all'alta mobilità e il reset dell'Ultimate, eccelle contro quasi ogni eroe se ben gestito."},{counterId:"valir",reason:"Generic Counter: Mantiene le distanze con repulsioni (Knockback) impedendo gli ingaggi frontali."}];export{e as H,o as g};
